mapper.update:
UPDATE borrow_record
SET status = 1, return_time = #{returnTime}, fine_amount = #{fineAmount}
WHERE id = #{id} AND status = 0

UPDATE borrow_record
SET due_date = #{dueDate}, renew_count = #{renewCount}
WHERE id = #{id}
  AND status = 0
  AND due_date = #{expectedDueDate}
  AND COALESCE(renew_count, 0) = #{expectedRenewCount}

UPDATE borrow_record
SET due_reminder_sent_time = #{reminderTime}
WHERE id = #{id}
  AND status = 0
  AND due_reminder_sent_time IS NULL

mapper.select:
SELECT COUNT(*) FROM borrow_record br
WHERE br.user_id = #{userId}
  AND br.book_id = #{bookId}
  AND br.status = 0

SELECT COUNT(*) FROM borrow_record br
WHERE br.status = 0 AND br.book_id IN

    #{bookId}

SELECT COALESCE(SUM(br.fine_amount), 0)
FROM borrow_record br
WHERE br.user_id = #{userId}

SELECT br.id, br.user_id, br.book_id, br.borrow_time, br.due_date, br.return_time, br.status, br.fine_amount, br.renew_count, br.due_reminder_sent_time, u.user_name, b.name AS book_name FROM borrow_record br LEFT JOIN user u ON br.user_id = u.id LEFT JOIN book b ON br.book_id = b.id
ORDER BY br.id DESC
LIMIT #{size} OFFSET #{current}
